const enrichWithIcons = (items: NavigateTypes[]): NavigateTypes[] => {
    return items.map((item) => {
        const icon = item.icon || ICON_MAP[item.label] || '';
        if (item.children) {
            return { ...item, icon, children: enrichWithIcons(item.children) };
        }
        return { ...item, icon };
    });
};

// Static entries for pages added to K3 that the backend may not have registered
// in pagePermission yet (Live Location Tracking, Face Training, etc.).
// pageIds 10001-10099 are reserved for static injections — they won't clash
// with real backend pageIds.
const STATIC_NEW_PAGES: NavigateTypes[] = [
    {
        label: 'Staff Attendance List',
        isTitle: false,
        icon: 'mdi mdi-calendar-text-outline',
        url: '/attendance/staff-attendance-list',
        pageId: 10001,
    },
    {
        label: 'Live Location Tracking',
        isTitle: false,
        icon: 'mdi mdi-map-marker-radius',
        url: '/attendance/live-location-tracking',
        pageId: 10002,
    },
    {
        label: 'Face Training',
        isTitle: false,
        icon: 'mdi mdi-face-recognition',
        url: '/attendance/face-training',
        pageId: 10003,
    },
];

// URLs that must always appear right after Staff Attendance in the sidebar,
// regardless of where the backend places them (DB ordering puts them after E-Mark).
const ATTENDANCE_SECTION_URLS = new Set([
    '/attendance/staff-attendance-list',
    '/attendance/live-location-tracking',
    '/attendance/face-training',
]);

const getUserNavigation = (): NavigateTypes[] => {
    const userDetails = localStorage.getItem('loginInfo');
    if (userDetails) {
        const localData = JSON.parse(userDetails);
        const backendPages = Array.isArray(localData) && localData[0]?.pagePermission;
        let pages: NavigateTypes[] = backendPages?.filter((p: any) => p.pageId) || [];

        // Pull out any attendance sub-pages from wherever the backend placed them
        // (they land after E-Mark because their page_ids are at the end of the DB table).
        const attendanceExtras = pages.filter((p: any) => p.url && ATTENDANCE_SECTION_URLS.has(p.url));

        // Add static fallbacks for any attendance pages missing from the backend entirely
        const backendUrls = new Set(pages.map((p: any) => p.url).filter(Boolean));
        const staticFallbacks = STATIC_NEW_PAGES.filter((p) => p.url && !backendUrls.has(p.url));

        const allAttendanceExtras = [...attendanceExtras, ...staticFallbacks];

        // Remove them from their current (possibly wrong) position
        let cleanedPages = pages.filter((p: any) => !p.url || !ATTENDANCE_SECTION_URLS.has(p.url));

        // Re-insert right after "Staff Attendance" so they group correctly under Attendance
        if (allAttendanceExtras.length > 0) {
            const staffAttIdx = cleanedPages.findIndex((p: any) => p.url === '/attendance/staff-attendance');
            if (staffAttIdx !== -1) {
                cleanedPages = [
                    ...cleanedPages.slice(0, staffAttIdx + 1),
                    ...allAttendanceExtras,
                    ...cleanedPages.slice(staffAttIdx + 1),
                ];
            } else {
                cleanedPages = [...cleanedPages, ...allAttendanceExtras];
            }
        }

        return enrichWithIcons(cleanedPages);
    }
    return [];
};

const Navigate = () => {
    const { dispatch, appSelector } = useRedux();

    const { getStaffAttendanceSuccess, getStaffAttendanceList, getStaffAttendanceFailure } = appSelector((state) => ({
        getStaffAttendanceSuccess: state.staffAttendanceReducer.getStaffAttendanceSuccess,
        getStaffAttendanceList: state.staffAttendanceReducer.getStaffAttendanceList,
        getStaffAttendanceFailure: state.staffAttendanceReducer.getStaffAttendanceFailure,
    }));

    const loginInfo = localStorage.getItem('loginInfo');
    const localData = loginInfo ? JSON.parse(loginInfo) : [];
    const staffId = localData[0]?.staffId;
    const roleIdforRole = localData[0].roleId;

    const [navigate, setNavigate] = useState<NavigateTypes[]>(getUserNavigation());

    // useEffect(() => {
    //     if (getStaffAttendanceSuccess) {
    //         const todayAttendance =
    //             roleIdforRole != 1
    //                 ?  getStaffAttendanceList?.find((att: any) => att.attendanceStatusId === 1 && att.staffId == staffId)
    //                 : true;
    //         const fullMenu = getUserNavigation();
    //         let filteredMenu: NavigateTypes[] = [];
    //         if (todayAttendance) {
    //             filteredMenu = fullMenu;
    //         } else {
    //             const attendanceAccess = (fullMenu as any[]).find((menu) => menu.pageId === 2);
    //             if (attendanceAccess) filteredMenu.push(attendanceAccess);
    //         }
    //         setNavigate(filteredMenu);
    //         dispatch(resetGetStaffAttendance());
    //     } else if (getStaffAttendanceFailure) {
    //         dispatch(resetGetStaffAttendance());
    //     }
    // }, [getStaffAttendanceSuccess, getStaffAttendanceFailure]);

    useEffect(() => {
        if (getStaffAttendanceSuccess) {
            const pageIds = [1, 2, 3, 4, 5];
            const todayAttendance =
                roleIdforRole !== 1
                    ? getStaffAttendanceList?.find(
                          (att: any) => att.attendanceStatusId === 1 && att.staffId === staffId
                      )
                    : true;

            const fullMenu: NavigateTypes[] = getUserNavigation();
            let filteredMenu: NavigateTypes[] = [];

            if (todayAttendance) {
                filteredMenu = fullMenu;
            } else {
                const attendanceAccess = fullMenu.filter((menu) => pageIds.includes(menu.pageId!));
                filteredMenu = attendanceAccess;
            }

            setNavigate(filteredMenu);
            dispatch(resetGetStaffAttendance());
        } else if (getStaffAttendanceFailure) {
            dispatch(resetGetStaffAttendance());
        }
    }, [getStaffAttendanceSuccess, getStaffAttendanceFailure]);

    useEffect(() => {
        const attendanceDate = {
            attendanceDate: moment().format('YYYY-MM-DD'),
            staffId: staffId,
        };
        dispatch(getStaffAttendanceRequest(attendanceDate));

        const handleStorageChange = () => {
            setNavigate(getUserNavigation()); // Update state when storage changes
        };

        window.addEventListener('storage', handleStorageChange);
        return () => {
            window.removeEventListener('storage', handleStorageChange);
        };
    }, []);

    return navigate;
};

